SourceCode.Declaration:
/// <summary>
/// Batch controller class for Post sales order shipment processing
/// </summary>
class METCustomerMDFConsolidationBatchController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METCustomerMDFConsolidationBatchController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METCustomerMDFConsolidationBatchController controller = new METCustomerMDFConsolidationBatchController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METCustomerMDFConsolidationBatchService), methodstr(METCustomerMDFConsolidationBatchService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METCustomerMDFConsolidationBatchController     controller;
    METCustomerMDFConsolidationBatchContract       contract;
    List                                            shipIdList = new List(Types::String);
    METThreadCount                                  threadCount = WHSParameters::find().METFinalisationThreadCount;
    str                                             listOfShipment;

    if (threadCount == 0)
    {
        throw error("@MET:ThreadCheck");
    }

    // create controller
    controller = METCustomerMDFConsolidationBatchController::construct(_args);

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmShowDialog(false);
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:ConfirmShipment";
}
